struct Base {
    virtual ~Base() { std::cout << "~Base\n"; }
};
struct Derived : Base {
    ~Derived() override { std::cout << "~Derived\n"; }
};

int main() {
    Base* p = new Derived;
    delete p;
}

// polymorphic base => public virtual destructor
struct Shape {
    virtual void draw() const = 0;
    virtual ~Shape() = default;
};

// or: forbid deleting through the base
struct Mixin {
protected:
    ~Mixin() = default;
};

// trivia: shared_ptr remembers the real type
std::shared_ptr<Base> sp = std::make_shared<Derived>();
